/* ==========================================================================
   App Shell Layout - CSS Grid System
   ========================================================================== */

/* ==========================================================================
   Matrix Background Canvas
   ========================================================================== */

.matrix-canvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -1;
}

/* ==========================================================================
   App Shell Grid Container
   ========================================================================== */

.app-shell {
  display: grid;
  grid-template-rows: auto auto 1fr auto;
  grid-template-columns: 180px 1fr;
  grid-template-areas:
    'header header'
    'banner banner'
    'sidebar main'
    'footer footer';
  height: 100vh;
  overflow: hidden;
  position: relative;
}

/* ==========================================================================
   Header
   ========================================================================== */

.app-header {
  grid-area: header;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 24px;
  background-color: rgb(0 0 0 / 50%);
  border-bottom: 1px solid var(--color-border-dim);
  position: relative;
  z-index: 2;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-prompt {
  font-size: 20px;
  font-weight: var(--font-weight-bold);
  color: var(--color-text-primary);
}

.header-logo {
  font-size: 14px;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text-primary);
  letter-spacing: 1px;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Search button */
.header-search-btn {
  background: none;
  border: 1px solid var(--color-border-dim);
  color: var(--color-text-secondary);
  font-family: var(--font-family-mono);
  font-size: 11px;
  padding: 4px 8px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
}

.header-search-btn:hover {
  color: var(--color-green-primary);
  border-color: var(--color-green-primary);
}

.header-search-btn:focus-visible {
  outline: 1px solid var(--color-green-primary);
  outline-offset: 1px;
}

.header-search-btn kbd {
  font-family: var(--font-family-mono);
  font-size: 10px;
  border: 1px solid currentColor;
  padding: 0 3px;
  border-radius: 2px;
}

/* ==========================================================================
   Sidebar
   ========================================================================== */

.app-sidebar {
  grid-area: sidebar;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background-color: rgb(0 0 0 / 50%);
  border-right: 1px solid var(--color-border-dim);
  overflow-y: auto;
  position: relative;
  z-index: 1;
}

.sidebar-nav {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sidebar-footer {
  padding: 16px;
}

/* Nav Item */
.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: var(--font-weight-normal);
  color: var(--color-text-secondary);
  text-decoration: none;
  border-radius: 0;
  transition: background-color 0.15s ease, color 0.15s ease;
}

.nav-item:hover {
  color: var(--color-text-primary);
  text-decoration: none;
}

.nav-item--active {
  background-color: var(--color-nav-active);
  color: var(--color-text-primary);
  font-weight: var(--font-weight-semibold);
}

.nav-item-icon {
  font-family: var(--font-family-mono);
  font-size: 14px;
}

/* Storage Quota */
.storage-quota {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.storage-quota-bar {
  width: 100%;
  height: 6px;
  background-color: var(--color-border-dim);
  border-radius: 3px;
  overflow: hidden;
}

.storage-quota-fill {
  height: 100%;
  background-color: var(--color-green-primary);
  transition: width 0.3s ease;
}

.storage-quota-text {
  font-size: 10px;
  color: var(--color-text-secondary);
}

/* ==========================================================================
   Main Content Area
   ========================================================================== */

.app-main {
  grid-area: main;
  overflow-y: auto;
  background-color: rgb(0 0 0 / 90%);
  position: relative;
  z-index: 1;
}

/* ==========================================================================
   Footer
   ========================================================================== */

.app-footer {
  grid-area: footer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 24px;
  background-color: rgb(0 0 0 / 50%);
  border-top: 1px solid var(--color-border-dim);
  position: relative;
  z-index: 1;
}

.footer-left,
.footer-center,
.footer-right {
  display: flex;
  align-items: center;
}

.footer-center {
  gap: 16px;
}

.footer-copyright {
  font-size: 9px;
  color: var(--color-border-dim);
}

.footer-link {
  font-size: 9px;
  color: var(--color-text-secondary);
  text-decoration: none;
  transition: color 0.15s ease;
}

.footer-link:hover {
  color: var(--color-text-primary);
  text-decoration: none;
}

/* Status Indicator */
.status-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  color: var(--color-text-secondary);
}

.status-indicator-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}

.status-indicator-dot--connected {
  background-color: var(--color-green-primary);
  box-shadow: var(--glow-green);
}

.status-indicator-dot--disconnected {
  background-color: var(--color-error);
}

.status-indicator-dot--loading {
  background-color: var(--color-text-secondary);
  animation: pulse 1.5s ease-in-out infinite;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.status-indicator-text {
  font-family: var(--font-family-mono);
}

/* ==========================================================================
   User Menu
   ========================================================================== */

.user-menu {
  position: relative;
}

.user-menu-trigger {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  font-size: 11px;
  color: var(--color-text-secondary);
  cursor: pointer;
  transition: color 0.15s ease;
  background: none;
  border: none;
  font-family: var(--font-family-mono);
}

.user-menu-trigger:hover {
  color: var(--color-text-primary);
}

.user-menu-caret {
  font-size: 8px;
}

.user-menu-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  min-width: 120px;
  background-color: var(--color-background);
  border: 1px solid var(--color-border-dim);
  border-radius: 4px;
  padding: 4px 0;
  z-index: 100;
}

/* Invisible bridge covering the gap between trigger and dropdown
   so the mouse doesn't leave .user-menu while crossing the 4px gap */
.user-menu-dropdown::before {
  content: '';
  position: absolute;
  top: -4px;
  left: 0;
  right: 0;
  height: 4px;
}

.user-menu-item {
  display: block;
  width: 100%;
  padding: 8px 12px;
  font-size: 11px;
  font-family: var(--font-family-mono);
  color: var(--color-text-secondary);
  text-align: left;
  text-decoration: none;
  background: none;
  border: none;
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.user-menu-item:hover {
  color: var(--color-text-primary);
  background-color: var(--color-nav-active);
  text-decoration: none;
}

/* ==========================================================================
   Mobile Responsive (768px breakpoint)
   ========================================================================== */

@media (max-width: 768px) {
  .app-shell {
    grid-template-columns: 1fr;
    grid-template-areas:
      'header'
      'banner'
      'main'
      'footer';
  }

  .app-sidebar {
    display: none;
  }
}

/* ==========================================================================
   Search Palette - Command Palette Overlay
   Terminal aesthetic: JetBrains Mono, green on black, sharp corners
   ========================================================================== */

/* Backdrop */
.search-backdrop {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 80%);
  z-index: 100;
  display: flex;
  justify-content: center;
  padding-top: 120px;
}

/* Palette container */
.search-palette {
  width: 600px;
  max-height: calc(100vh - 200px);
  background: var(--color-black);
  border: 1px solid var(--color-green-primary);
  border-radius: 0;
  display: flex;
  flex-direction: column;
  font-family: var(--font-family-mono);
  overflow: hidden;
  align-self: flex-start;
}

/* Search input row */
.search-input-row {
  display: flex;
  align-items: center;
  padding: 14px 20px;
  border-bottom: 1px solid var(--color-border-dim);
  gap: 12px;
}

.search-icon {
  color: var(--color-text-secondary);
  font-size: 14px;
  flex-shrink: 0;
}

.search-input {
  flex: 1;
  background: none;
  border: none;
  color: var(--color-text-primary);
  font-family: var(--font-family-mono);
  font-size: 14px;
  outline: none;
  caret-color: var(--color-green-primary);
}

.search-input::placeholder {
  color: var(--color-text-dim);
}

.search-input:focus-visible {
  outline: none;
}

.search-esc-hint {
  color: var(--color-text-dim);
  font-size: 9px;
  border: 1px solid var(--color-text-dim);
  padding: 1px 4px;
  flex-shrink: 0;
}

/* Results */
.search-results {
  flex: 1;
  overflow-y: auto;
  max-height: 400px;
}

.search-result-item {
  display: flex;
  align-items: center;
  padding: 10px 20px;
  cursor: pointer;
  gap: 14px;
  border-left: 2px solid transparent;
  border-right: 2px solid transparent;
  border-top: 1px solid transparent;
  border-bottom: 1px solid var(--color-border-dim);
}

.search-result-item:hover,
.search-result-item.selected {
  background: var(--color-nav-active);
  border-color: var(--color-green-primary);
}

.search-result-icon {
  color: var(--color-text-secondary);
  font-size: 14px;
  flex-shrink: 0;
  width: 20px;
  text-align: center;
}

.search-result-item.selected .search-result-icon,
.search-result-icon.icon-bright {
  color: var(--color-green-primary);
}

.search-result-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.search-result-name {
  color: var(--color-text-primary);
  font-size: 12px;
  font-weight: var(--font-weight-normal);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-item.selected .search-result-name {
  font-weight: var(--font-weight-semibold);
}

.search-result-name mark {
  background: none;
  color: var(--color-green-primary);
  text-decoration: underline;
}

.search-result-path {
  color: var(--color-text-secondary);
  font-size: 10px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.search-result-date {
  color: var(--color-text-dim);
  font-size: 10px;
  flex-shrink: 0;
  text-align: right;
}

/* Empty/building states */
.search-building,
.search-no-results {
  padding: 24px 16px;
  color: var(--color-text-dim);
  font-size: 12px;
  text-align: center;
}

/* Footer */
.search-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px;
  border-top: 1px solid var(--color-border-dim);
}

.search-footer-hints {
  color: var(--color-text-dim);
  font-size: 9px;
}

.search-footer-hints kbd {
  display: inline;
  font-family: var(--font-family-mono);
  font-size: 9px;
  color: var(--color-text-secondary);
}

.search-footer-count {
  color: var(--color-text-dim);
  font-size: 9px;
}

/* ==========================================================================
   Responsive
   ========================================================================== */

@media (max-width: 768px) {
  .search-palette {
    width: calc(100vw - 32px);
  }

  .search-backdrop {
    padding-top: 80px;
  }
}

import { type Page, type Locator } from '@playwright/test';

/**
 * Page object for SearchPalette component interactions.
 *
 * Encapsulates the command palette overlay used for searching files and folders.
 * Provides locator methods for DOM elements and action methods for interactions.
 */
export class SearchPalettePage {
  constructor(private readonly page: Page) {}

  // ---------------------------------------------------------------------------
  // Locator methods
  // ---------------------------------------------------------------------------

  /**
   * The full-screen backdrop overlay (also has role="dialog").
   */
  backdrop(): Locator {
    return this.page.locator('.search-backdrop');
  }

  /**
   * The palette container (centered card with input + results).
   */
  palette(): Locator {
    return this.page.locator('.search-palette');
  }

  /**
   * The search text input.
   */
  input(): Locator {
    return this.page.locator('.search-input');
  }

  /**
   * The results container (role="listbox").
   */
  resultsList(): Locator {
    return this.page.locator('.search-results[role="listbox"]');
  }

  /**
   * All result item elements.
   */
  resultItems(): Locator {
    return this.page.locator('.search-result-item');
  }

  /**
   * A specific result item by zero-based index.
   */
  resultItem(index: number): Locator {
    return this.page.locator(`.search-result-item:nth-child(${index + 1})`);
  }

  /**
   * The name element within a specific result item.
   */
  resultName(index: number): Locator {
    return this.resultItem(index).locator('.search-result-name');
  }

  /**
   * The "no results" message element.
   */
  noResults(): Locator {
    return this.page.locator('.search-no-results');
  }

  /**
   * The "building index..." indicator.
   */
  buildingIndicator(): Locator {
    return this.page.locator('.search-building');
  }

  /**
   * The footer bar with keyboard hints and result count.
   */
  footer(): Locator {
    return this.page.locator('.search-footer');
  }

  /**
   * The result count text in the footer (e.g., "// 3 results").
   */
  footerCount(): Locator {
    return this.page.locator('.search-footer-count');
  }

  /**
   * The search button in the app header.
   */
  headerSearchButton(): Locator {
    return this.page.locator('.header-search-btn');
  }

  // ---------------------------------------------------------------------------
  // Action methods
  // ---------------------------------------------------------------------------

  /**
   * Wait for the search palette to become visible.
   */
  async waitForOpen(options?: { timeout?: number }): Promise<void> {
    await this.backdrop().waitFor({ state: 'visible', ...options });
  }

  /**
   * Wait for the search palette to close (hidden or detached).
   */
  async waitForClosed(options?: { timeout?: number }): Promise<void> {
    await this.backdrop().waitFor({ state: 'hidden', ...options });
  }

  /**
   * Type a query into the search input.
   */
  async typeQuery(text: string): Promise<void> {
    await this.input().fill(text);
  }

  /**
   * Clear the search input.
   */
  async clearQuery(): Promise<void> {
    await this.input().fill('');
  }

  /**
   * Get the number of visible result items.
   */
  async getResultCount(): Promise<number> {
    return await this.resultItems().count();
  }

  /**
   * Get an array of result name texts.
   */
  async getResultNames(): Promise<string[]> {
    const items = this.page.locator('.search-result-item .search-result-name');
    const count = await items.count();
    const names: string[] = [];
    for (let i = 0; i < count; i++) {
      const text = await items.nth(i).textContent();
      if (text) names.push(text);
    }
    return names;
  }

  /**
   * Click a result item by zero-based index.
   */
  async clickResult(index: number): Promise<void> {
    await this.resultItem(index).click();
  }

  /**
   * Check whether the palette backdrop is currently visible.
   */
  async isOpen(): Promise<boolean> {
    return await this.backdrop().isVisible();
  }

  /**
   * Get the footer count text (e.g., "// 3 results").
   */
  async getFooterCountText(): Promise<string> {
    return (await this.footerCount().textContent()) ?? '';
  }

  /**
   * Wait for at least one result item to become visible.
   */
  async waitForResults(options?: { timeout?: number }): Promise<void> {
    await this.resultItems()
      .first()
      .waitFor({ state: 'visible', ...options });
  }

  /**
   * Find the index of the currently selected (highlighted) result item.
   * Returns -1 if no item has the "selected" class.
   */
  async selectedResultIndex(): Promise<number> {
    const items = this.resultItems();
    const count = await items.count();
    for (let i = 0; i < count; i++) {
      const className = await items.nth(i).getAttribute('class');
      if (className?.includes('selected')) {
        return i;
      }
    }
    return -1;
  }
}

