  1→import { useState, useCallback, useEffect, useRef } from 'react';
  2→import { useFolderStore } from '../stores/folder.store';
  3→import { useAuthStore } from '../stores/auth.store';
  4→import { searchIndexService, type SearchResult } from '../services/search-index.service';
  5→
  6→// ---------------------------------------------------------------------------
  7→// Module-level callback for triggering index rebuild from outside React tree
  8→// ---------------------------------------------------------------------------
  9→
 10→let _rebuildCallback: (() => void) | null = null;
 11→
 12→export function registerRebuildCallback(cb: () => void): void {
 13→  _rebuildCallback = cb;
 14→}
 15→
 16→export function triggerSearchIndexRebuild(): void {
 17→  _rebuildCallback?.();
 18→}
